// ===== WatchPost API (action-routed) =====
// CHANGE THESE before activating the workflow.
const OWNER_EMAIL = 'akalugwusuccess87@gmail.com';
const OWNER_PASSWORD = 'change-me-please';
const INGEST_KEY = 'change-this-camera-key';
const USE_AI = true;            // false = skip the AI and store the event as-is
const MAX_ALERTS = 100;
const MAX_PHOTOS = 5;           // photos per person (People screen)
const MAX_PHOTO_CHARS = 215000; // ~160 KB per photo; 640px JPEGs are usually 40-80 KB
const MAX_INBOX_CHARS = 3000000; // total photo inbox size before addPerson is refused

const SETUP_DONE = OWNER_PASSWORD !== 'change-me-please' && INGEST_KEY !== 'change-this-camera-key';

const store = $getWorkflowStaticData('global');
if (!store.alerts) store.alerts = [];
if (!store.tokens) store.tokens = {};
if (!store.people) store.people = [];
if (!store.faceInbox) store.faceInbox = [];
if (!store.cameras) {
  store.cameras = [
    { id: 'cam-1', name: 'Front door', location: 'Front of house', image: 'assets/images/front-door.jpg', enabled: true, source: '' },
    { id: 'cam-2', name: 'Gate', location: 'Driveway', image: 'assets/images/gate.jpg', enabled: true, source: '' },
    { id: 'cam-3', name: 'Backyard', location: 'Back of house', image: 'assets/images/backyard.jpg', enabled: false, source: '' },
  ];
}
const reply = (status, data) => [{ json: { status, body: data } }];

function saveAlert(alert) {
  store.alerts.unshift(alert);
  store.alerts = store.alerts.slice(0, MAX_ALERTS);
  // Keep embedded snapshots only on the newest 30 alerts (workflow storage is small).
  store.alerts.forEach((a, i) => {
    if (i >= 30 && String(a.image).startsWith('data:')) {
      const c = store.cameras.find((x) => x.name === a.cameraName);
      a.image = c ? c.image : 'assets/images/night-car.jpg';
    }
  });
}

const req = $input.first().json;
const body = req.body || {};
const headers = req.headers || {};
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
const action = body.action;

// Safety: do not run with the sample password / camera key.
if (!SETUP_DONE) {
  return reply(503, { error: 'Setup not finished: change OWNER_PASSWORD and INGEST_KEY in the n8n API node.' });
}

const findPerson = (name) => {
  const n = String(name || '').trim().toLowerCase();
  return store.people.find((p) => p.name.toLowerCase() === n && p.status !== 'deleting') || null;
};
// Camera address typed in the app: "192.168.1.50:8080" (IP Webcam) or a full http(s)/rtsp URL.
const cleanSource = (s) => {
  let v = String(s || '').trim().replace(/\/+$/, '');
  if (v.length > 200 || /\s/.test(v)) return null;
  if (v === '') return '';
  if (/^(https?|rtsp):\/\/[^\s\/]+/i.test(v)) return v;
  if (/^[A-Za-z0-9.\-]+(:\d{1,5})?$/.test(v)) return v;   // host or host:port
  return null;
};
const stripDataUrl = (s) => String(s).replace(/^data:[^,]*,/, '');
// Keeps letters from any language (Igbo/Yoruba accents etc.), digits, space, _ and -
const folderName = (name) => String(name).replace(/[^\p{L}\p{N} _-]/gu, '').trim();

// Plain sentence for a known person (used when the AI is off or fails).
function knownLine(name, cameraName) {
  const p = findPerson(name);
  const spot = cameraName.toLowerCase();
  if (p && p.relation) return 'Your ' + p.relation + ', ' + p.name + ', is at the ' + spot + '.';
  return name + ' is at the ' + spot + '.';
}

function buildPrompt(cam, hint, personName) {
  const p = personName !== 'Unknown' ? findPerson(personName) : null;
  const who = personName === 'Unknown'
    ? 'The home camera system did not recognise anyone.'
    : 'The home camera system recognised this person as ' + personName +
      (p && p.relation ? " (the homeowner's " + p.relation + ')' : '') +
      '. Use this name; do not question it.';
  return [
    'You are the warm, friendly voice of a family home security app. Talk to the homeowner like a kind, caring assistant.',
    'Look at the camera frame and reply with ONLY a JSON object, no other text:',
    '{"subject":"person|vehicle|animal|package|other|nothing","kind":"person|vehicle|motion","tags":["short lowercase tags"],"sentence":"..."}',
    '"tags": 1 to 6 short lowercase tags for things you can clearly see, e.g. "person", "shopping bags", "umbrella", "white car", "dog", "parcel".',
    '"sentence": one or two short, kind sentences (under 30 words in total) to be read aloud. Mention the camera spot. ' +
      'If a recognised person is given, greet them by name and relationship, e.g. "Your wife Ada is coming up to the front door with shopping bags. You might want to get the door." ' +
      'You may add one gentle, practical suggestion (get the door, collect the parcel, no need to worry). ' +
      'For people who are not recognised, calmly and politely describe their clothing and what they carry. Never accuse anyone.',
    'Never identify anyone from their face yourself and never guess names. Only use the recognised name given below.',
    'Use subject "nothing" when there is no meaningful activity (shadows, lighting change, insects, camera noise).',
    '',
    'Camera: ' + cam.name + ' (' + cam.location + '). Motion detector guess: ' + hint + '.',
    who,
    'Reply with the JSON object only.',
  ].join('\n');
}

// ---- Camera / detector pushes an event (uses x-api-key) ----
if (action === 'ingest') {
  if (headers['x-api-key'] !== INGEST_KEY) return reply(401, { error: 'Bad API key' });
  const cam = store.cameras.find(
    (c) => c.name.toLowerCase() === String(body.camera || '').toLowerCase()
  );
  if (!cam) return reply(404, { error: 'Unknown camera: ' + body.camera });
  if (!cam.enabled) return reply(200, { ok: true, ignored: 'camera is off' });

  const hint = ['person', 'vehicle', 'motion'].includes(body.kind) ? body.kind : 'motion';
  let image = body.image || cam.image;
  if (typeof image !== 'string' || image.length > 70000) image = cam.image;
  const ts = Number(body.ts) || Date.now();
  const personName = body.name ? String(body.name).slice(0, 40) : 'Unknown';
  const person = personName !== 'Unknown' ? findPerson(personName) : null;
  const ingest = {
    id: uid(),
    cameraName: cam.name,
    image,
    kind: hint,
    personName,
    relation: person && person.relation ? person.relation : null,
    tags: [],
    time: ts,
    seen: false,
  };
  const plainKnown = personName !== 'Unknown' ? knownLine(personName, cam.name) : null;

  const frame =
    typeof body.analysisImage === 'string' && body.analysisImage.length <= 700000
      ? stripDataUrl(body.analysisImage)
      : null;

  if (USE_AI && frame) {
    return [{
      json: {
        needsAI: true,
        ingest,
        knownLine: plainKnown,
        prompt: buildPrompt(cam, hint, personName),
        frame,
      },
    }];
  }

  if (plainKnown) {
    ingest.kind = 'person';
    ingest.tags = ['person'];
    ingest.summary = plainKnown;
  }
  saveAlert(ingest);
  return reply(200, { ok: true, id: ingest.id, summary: ingest.summary || null });
}

// ---- edge.py face inbox (uses x-api-key) ----
if (action === 'pendingFaces' || action === 'ackFaces') {
  if (headers['x-api-key'] !== INGEST_KEY) return reply(401, { error: 'Bad API key' });
  if (action === 'pendingFaces') {
    const cameras = store.cameras.map((c) => ({ id: c.id, name: c.name, enabled: !!c.enabled, source: c.source || '' }));
    return reply(200, { items: store.faceInbox, cameras });
  }
  const ids = Array.isArray(body.ids) ? body.ids.map(String) : [];
  const done = store.faceInbox.filter((i) => ids.includes(i.id));
  store.faceInbox = store.faceInbox.filter((i) => !ids.includes(i.id));
  for (const item of done) {
    if (item.op === 'add') {
      store.people = store.people.map((p) =>
        p.id === item.personId ? { ...p, status: 'enrolled', enrolledAt: Date.now() } : p
      );
    }
    if (item.op === 'delete') store.people = store.people.filter((p) => p.id !== item.personId);
  }
  return reply(200, { ok: true, cleared: done.length });
}

// ---- App login ----
if (action === 'login') {
  const email = String(body.email || '').trim().toLowerCase();
  const now = Date.now();
  // Brute-force guard: 8 wrong tries -> locked for 10 minutes.
  const lock = store.loginLock || { fails: 0, until: 0 };
  if (lock.until > now) return reply(429, { error: 'Too many wrong tries. Wait 10 minutes and try again.' });
  if (email !== OWNER_EMAIL.toLowerCase() || body.password !== OWNER_PASSWORD) {
    lock.fails = (lock.fails || 0) + 1;
    if (lock.fails >= 8) { lock.until = now + 10 * 60 * 1000; lock.fails = 0; }
    store.loginLock = lock;
    return reply(401, { error: 'Wrong email or password' });
  }
  store.loginLock = { fails: 0, until: 0 };
  for (const t of Object.keys(store.tokens)) if (store.tokens[t] < now) delete store.tokens[t];
  const token = uid() + uid() + uid();
  store.tokens[token] = now + 30 * 24 * 3600 * 1000;
  return reply(200, { token });
}

// ---- Everything below needs a valid session token (x-token) ----
const token = headers['x-token'];
const exp = token ? store.tokens[token] : null;
if (!exp || exp < Date.now()) return reply(401, { error: 'Session expired' });

switch (action) {
  case 'getState': {
    // The app lists ids it already holds a snapshot for; we skip re-sending those images.
    const have = new Set(Array.isArray(body.have) ? body.have.map(String) : []);
    const alerts = store.alerts.map((a) =>
      have.has(a.id) && String(a.image).startsWith('data:') ? { ...a, image: '' } : a
    );
    return reply(200, { alerts, cameras: store.cameras, people: store.people });
  }
  case 'markSeen':
    store.alerts = store.alerts.map((a) => (a.id === body.id ? { ...a, seen: true } : a));
    return reply(200, { ok: true });
  case 'markAllSeen':
    store.alerts = store.alerts.map((a) => ({ ...a, seen: true }));
    return reply(200, { ok: true });
  case 'deleteAlert':
    store.alerts = store.alerts.filter((a) => a.id !== body.id);
    return reply(200, { ok: true });
  case 'setCameras':
    if (!Array.isArray(body.cameras)) return reply(400, { error: 'cameras must be a list' });
    const cleaned = [];
    for (const c of body.cameras) {
      const source = cleanSource(c.source);
      if (source === null) return reply(400, { error: 'Camera address for "' + String(c.name) + '" looks wrong. Use e.g. 192.168.1.50:8080' });
      cleaned.push({
        id: String(c.id),
        name: String(c.name).trim().slice(0, 40),
        location: String(c.location || 'Not set').slice(0, 60),
        image: String(c.image).slice(0, 200),
        enabled: !!c.enabled,
        source,
      });
    }
    const names = cleaned.map((c) => c.name.toLowerCase());
    if (names.some((n, i) => !n || names.indexOf(n) !== i)) return reply(400, { error: 'Each camera needs a different, non-empty name' });
    store.cameras = cleaned;
    return reply(200, { ok: true });
  case 'listPeople':
    return reply(200, { people: store.people });
  case 'addPerson': {
    const name = String(body.name || '').trim().slice(0, 40);
    const relation = String(body.relation || '').trim().slice(0, 30) || null;
    const photos = Array.isArray(body.photos) ? body.photos : [];
    if (!name || !folderName(name)) return reply(400, { error: 'name is required (letters, numbers, spaces)' });
    if (store.people.some((p) => p.status !== 'deleting' && folderName(p.name).toLowerCase() === folderName(name).toLowerCase())) {
      return reply(409, { error: 'A person with a very similar name already exists' });
    }
    if (findPerson(name)) return reply(409, { error: name + ' is already enrolled' });
    if (photos.length < 1 || photos.length > MAX_PHOTOS) {
      return reply(400, { error: 'send 1 to ' + MAX_PHOTOS + ' photos' });
    }
    if (photos.some((ph) => typeof ph !== 'string' || ph.length > MAX_PHOTO_CHARS)) {
      return reply(413, { error: 'each photo must be a base64 JPEG under about 150 KB (resize to 640px)' });
    }
    const clean = photos.map(stripDataUrl);
    const inboxSize = store.faceInbox.reduce(
      (n, i) => n + (i.photos || []).reduce((m, p) => m + p.length, 0), 0
    );
    const newSize = clean.reduce((n, p) => n + p.length, 0);
    if (inboxSize + newSize > MAX_INBOX_CHARS) {
      return reply(503, { error: 'Photo inbox is full. Make sure edge.py is running, then try again.' });
    }
    const person = {
      id: uid(),
      name,
      relation,
      status: 'pending',
      photoCount: clean.length,
      createdAt: Date.now(),
    };
    store.people.push(person);
    store.faceInbox.push({
      id: uid(),
      op: 'add',
      personId: person.id,
      name,
      folder: folderName(name),
      photos: clean,
      createdAt: Date.now(),
    });
    return reply(200, { ok: true, person });
  }
  case 'deletePerson': {
    const person = store.people.find((p) => p.id === body.id);
    if (!person) return reply(404, { error: 'Person not found' });
    if (person.status === 'deleting') return reply(200, { ok: true, removed: false, status: 'deleting' });
    const pendingAdd = store.faceInbox.find((i) => i.op === 'add' && i.personId === person.id);
    if (pendingAdd) {
      // edge.py never received the photos, so just drop everything here.
      store.faceInbox = store.faceInbox.filter((i) => i.id !== pendingAdd.id);
      store.people = store.people.filter((p) => p.id !== person.id);
      return reply(200, { ok: true, removed: true });
    }
    store.people = store.people.map((p) => (p.id === person.id ? { ...p, status: 'deleting' } : p));
    store.faceInbox.push({
      id: uid(),
      op: 'delete',
      personId: person.id,
      name: person.name,
      folder: folderName(person.name),
      createdAt: Date.now(),
    });
    return reply(200, { ok: true, removed: false, status: 'deleting' });
  }
  // ---- Demo tools (app -> "Demo tools"): canned alerts, no camera or AI needed ----
  case 'testAlert': {
    const cam = store.cameras.find((x) => x.name.toLowerCase() === String(body.camera || '').toLowerCase())
      || store.cameras.find((x) => x.enabled) || store.cameras[0];
    if (!cam) return reply(400, { error: 'Add a camera first' });
    const spot = cam.name.toLowerCase();
    const scenario = ['known', 'stranger', 'vehicle'].includes(body.scenario) ? body.scenario : 'known';
    const alert = { id: uid(), cameraName: cam.name, image: cam.image, kind: 'person', personName: 'Unknown',
                    relation: null, tags: [], time: Date.now(), seen: false };
    if (scenario === 'known') {
      const p = store.people.find((x) => x.status !== 'deleting') || { name: 'Ada', relation: 'wife' };
      alert.personName = p.name;
      alert.relation = p.relation || null;
      alert.tags = ['person', 'shopping bags'];
      alert.summary = (p.relation ? 'Your ' + p.relation + ', ' + p.name : p.name) +
        ', is coming up to the ' + spot + ' with shopping bags. You might want to get the door.';
    } else if (scenario === 'stranger') {
      alert.tags = ['person', 'blue jacket', 'parcel'];
      alert.summary = 'Someone in a blue jacket is at the ' + spot + ', holding a parcel. Nothing to worry about, but you may want to take a look.';
    } else {
      alert.kind = 'vehicle';
      alert.image = 'assets/images/night-car.jpg';
      alert.tags = ['vehicle', 'white car'];
      alert.summary = 'A white car has stopped near the ' + spot + '.';
    }
    saveAlert(alert);
    return reply(200, { ok: true, id: alert.id });
  }
  case 'clearAlerts':
    store.alerts = [];
    return reply(200, { ok: true });
  case 'logout':
    delete store.tokens[token];
    return reply(200, { ok: true });
  default:
    return reply(400, { error: 'Unknown action: ' + action });
}

// ===== WatchPost Save (runs after the AI step) =====
// If the AI failed or is out of credit, we still store a plain alert.
const MAX_ALERTS = 100;

const store = $getWorkflowStaticData('global');
if (!store.alerts) store.alerts = [];
if (!store.cameras) store.cameras = [];
const reply = (status, data) => [{ json: { status, body: data } }];

function saveAlert(alert) {
  store.alerts.unshift(alert);
  store.alerts = store.alerts.slice(0, MAX_ALERTS);
  // Keep embedded snapshots only on the newest 30 alerts (workflow storage is small).
  store.alerts.forEach((a, i) => {
    if (i >= 30 && String(a.image).startsWith('data:')) {
      const c = store.cameras.find((x) => x.name === a.cameraName);
      a.image = c ? c.image : 'assets/images/night-car.jpg';
    }
  });
}

const src = $('API').first().json;
const res = $input.first().json || {};
const alert = { ...src.ingest };

// Read the AI text (the Anthropic node returns content blocks).
let text = '';
if (Array.isArray(res.content)) {
  const block = res.content.find((c) => c && c.type === 'text');
  text = block ? block.text : '';
} else if (typeof res.content === 'string') {
  text = res.content;
} else if (typeof res.text === 'string') {
  text = res.text;
} else if (typeof res.merged_response === 'string') {
  text = res.merged_response;
}

let ai = null;
try {
  const m = String(text).match(/\{[\s\S]*\}/);
  ai = m ? JSON.parse(m[0]) : null;
} catch (e) {
  ai = null;
}

const known = src.ingest.personName && src.ingest.personName !== 'Unknown';
if (ai && ai.subject === 'nothing' && !known) {
  return reply(200, { ok: true, ignored: 'nothing of interest' });
}

if (ai) {
  if (['person', 'vehicle', 'motion'].includes(ai.kind)) alert.kind = ai.kind;
  else if (ai.subject === 'person') alert.kind = 'person';
  else if (ai.subject === 'vehicle') alert.kind = 'vehicle';
  else alert.kind = 'motion';
  if (ai.sentence) alert.summary = String(ai.sentence).slice(0, 240);
  if (Array.isArray(ai.tags)) {
    alert.tags = ai.tags
      .filter((t) => typeof t === 'string' && t.trim())
      .map((t) => t.trim().toLowerCase().slice(0, 30))
      .slice(0, 6);
  }
}

if (known) {
  // Recognised by edge.py: keep the friendly AI sentence, fall back to the plain one.
  alert.personName = src.ingest.personName;
  alert.kind = 'person';
  if (!alert.summary) alert.summary = src.knownLine;
  if (!alert.tags || alert.tags.length === 0) alert.tags = ['person'];
}

saveAlert(alert);
return reply(200, {
  ok: true,
  id: alert.id,
  summary: alert.summary || null,
  tags: alert.tags || [],
  ai: !!ai,
});
